import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry triu_matmul(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    .reg .pred %p<12>;
    .reg .s32  %r<40>;
    .reg .s64  %rd<12>;
    .reg .f32  %f<8>;
    .shared .align 4 .f32 As[1024];
    .shared .align 4 .f32 Bs[1024];
    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1,  [N];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ctaid.y;
    mov.u32 %r4, %tid.x;
    mov.u32 %r5, %tid.y;
    mad.lo.s32 %r6, %r3, 32, %r5;   // row
    mad.lo.s32 %r7, %r2, 32, %r4;   // col
    setp.lt.s32 %p1, %r6, %r1;      // row_valid
    setp.lt.s32 %p2, %r7, %r1;      // col_valid
    add.s32 %r8, %r1, 31;
    shr.u32 %r9, %r8, 5;            // numTiles = (N+31)/32
    mov.f32 %f1, 0f00000000;        // accumulator
    mov.u32 %r10, 0;                // t
    mov.u32 %r18, As;
    mov.u32 %r19, Bs;
    mul.lo.s32 %r16, %r5, 128;
    mad.lo.s32 %r16, %r4, 4, %r16;  // shared store offset = ty*128 + tx*4
    add.s32 %r20, %r18, %r16;       // As store addr
    add.s32 %r21, %r19, %r16;       // Bs store addr
    mul.lo.s32 %r23, %r5, 128;      // ty*128 (As row base)
    mul.lo.s32 %r24, %r4, 4;        // tx*4   (Bs col base)
TILE_LOOP:
    setp.ge.s32 %p3, %r10, %r9;
    @%p3 bra TILE_LOOP_END;
    mad.lo.s32 %r11, %r10, 32, %r4; // Aidx_col = t*32 + tx
    setp.lt.s32 %p4, %r11, %r1;
    and.pred %p5, %p1, %p4;
    mov.f32 %f2, 0f00000000;
    @!%p5 bra SKIP_A_LOAD;
    mad.lo.s32 %r14, %r6, %r1, %r11;
    mul.wide.s32 %rd4, %r14, 4;
    add.s64 %rd5, %rd1, %rd4;
    ld.global.f32 %f2, [%rd5];
SKIP_A_LOAD:
    st.shared.f32 [%r20], %f2;
    mad.lo.s32 %r12, %r10, 32, %r5; // Bidx_row = t*32 + ty
    setp.lt.s32 %p6, %r12, %r1;
    and.pred %p7, %p6, %p2;
    mov.f32 %f3, 0f00000000;
    @!%p7 bra SKIP_B_LOAD;
    mad.lo.s32 %r15, %r12, %r1, %r7;
    mul.wide.s32 %rd6, %r15, 4;
    add.s64 %rd7, %rd2, %rd6;
    ld.global.f32 %f3, [%rd7];
SKIP_B_LOAD:
    st.shared.f32 [%r21], %f3;
    bar.sync 0;
    mov.u32 %r22, 0;   // k
INNER_LOOP:
    setp.ge.s32 %p8, %r22, 32;
    @%p8 bra INNER_LOOP_END;
    mad.lo.s32 %r25, %r22, 4, %r23;   // As offset
    add.s32 %r26, %r18, %r25;         // As addr
    ld.shared.f32 %f4, [%r26];
    mad.lo.s32 %r27, %r22, 128, %r24; // Bs offset
    add.s32 %r28, %r19, %r27;         // Bs addr
    ld.shared.f32 %f5, [%r28];
    fma.rn.f32 %f1, %f4, %f5, %f1;
    add.s32 %r22, %r22, 1;
    bra INNER_LOOP;
INNER_LOOP_END:
    bar.sync 0;
    add.s32 %r10, %r10, 1;
    bra TILE_LOOP;
TILE_LOOP_END:
    and.pred %p9, %p1, %p2;
    @!%p9 bra DONE;
    mad.lo.s32 %r31, %r6, %r1, %r7;
    mul.wide.s32 %rd8, %r31, 4;
    add.s64 %rd9, %rd3, %rd8;
    setp.lt.s32 %p10, %r7, %r6;   // col < row -> zero out
    @%p10 bra STORE_ZERO;
    st.global.f32 [%rd9], %f1;
    bra DONE;
STORE_ZERO:
    mov.f32 %f6, 0f00000000;
    st.global.f32 [%rd9], %f6;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("triu_matmul")

class ModelNew(nn.Module):
    """
    Model that performs matrix multiplication (C = A * B) for upper triangular matrices
    using a custom PTX kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        assert A.shape == B.shape
        assert A.dim() == 2 and A.shape[0] == A.shape[1]
        N = A.shape[0]

        A = A.contiguous()
        B = B.contiguous()

        C = torch.empty((N, N), dtype=A.dtype, device=A.device)

        module = _get_ptx_module()

        block_x, block_y = 32, 32
        grid_x = (N + block_x - 1) // block_x
        grid_y = (N + block_y - 1) // block_y

        module.launch(
            "triu_matmul",
            grid=(grid_x, grid_y, 1),
            block=(block_x, block_y, 1),
            arguments=[A, B, C, i32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C

